import re
import glob

bool_flags = set()
value_flags = set()

for file in glob.glob("mock_help/*.txt"):
    with open(file) as f:
        in_flags = False
        for line in f:
            if line.startswith("Flags:") or line.startswith("Formatting") or line.startswith("Filtering") or line.startswith("Sorting"):
                in_flags = True
                continue
            if line.startswith("Commands:") or line.startswith("Arguments:"):
                in_flags = False
                continue

            if in_flags:
                if "  -" in line or "  --" in line:
                    # extract left part
                    parts = line.split("  ")
                    for p in parts:
                        p = p.strip()
                        if p.startswith("-"):
                            for f_part in p.split(","):
                                f_part = f_part.strip().split(" ")[0]
                                if "=" in f_part:
                                    flag_name = f_part.split("=")[0]
                                    value_flags.add(flag_name)
                                else:
                                    bool_flags.add(f_part)
                            break

bool_flags.discard('--help')
bool_flags.discard('-h')

print("Bools:", sorted(list(bool_flags)))
print("Values:", sorted(list(value_flags)))
