import glob

bool_flags = set()
value_flags = set()

for file in glob.glob("mock_help/*.txt"):
    with open(file) as f:
        in_flags = False
        for line in f:
            if line.startswith("Flags:") or line.startswith("Formatting") or line.startswith("Filtering") or line.startswith("Sorting"):
                in_flags = True
                continue
            if line.startswith("Commands:") or line.startswith("Arguments:"):
                in_flags = False
                continue

            if in_flags:
                if "  -" in line or "  --" in line:
                    parts = line.split("  ")
                    for p in parts:
                        p = p.strip()
                        if p.startswith("-"):
                            aliases = []
                            has_value = "=" in p
                            # Handle cases like `--created=DATE` and `--created DATE` (it uses =)
                            for f_part in p.split(","):
                                f_part = f_part.strip().split(" ")[0].split("=")[0]
                                if f_part.startswith("-"):
                                    aliases.append(f_part)
                            if has_value:
                                value_flags.update(aliases)
                            else:
                                bool_flags.update(aliases)
                            break

bool_flags -= {"-h", "--help", "--version"}
value_flags -= {"-h", "--help", "--version"}
bool_flags -= value_flags # if it appeared as value somewhere, it's a value flag

print("Bools:", sorted(list(bool_flags)))
print("Values:", sorted(list(value_flags)))
